import numpy as np

def covariance_matrix(X):
    A = np.array(X, dtype=float)
    if A.ndim != 2 or len(A) == 0:
        raise ValueError('need at least one row')
    C = A - A.mean(axis=0)
    return (C.T @ C / len(A)).tolist()


def pca_fit(X, k):
    A = np.array(X, dtype=float)
    if A.ndim != 2 or len(A) == 0 or not 1 <= k <= A.shape[1]:
        raise ValueError('need at least one row and 1 <= k <= number of features')
    if np.all(A == A[0]):
        raise ValueError('the data has no spread')
    values, vectors = np.linalg.eigh(np.array(covariance_matrix(A)))
    order = np.argsort(values)[::-1]
    values, vectors = values[order], vectors[:, order]
    total = values.sum()
    components = []
    for j in range(k):
        u = vectors[:, j]
        if u[np.argmax(np.abs(u) > 1e-9)] < 0:
            u = -u
        components.append(u.tolist())
    return {'mean': A.mean(axis=0).tolist(), 'components': components,
            'variances': values[:k].tolist(), 'explained': (values[:k] / total).tolist()}


def pca_transform(model, X):
    A = np.array(X, dtype=float).reshape(-1, len(model['mean']))
    return ((A - np.array(model['mean'])) @ np.array(model['components']).T).tolist()

