import numpy as np


def project(X, components):
    X = np.asarray(X, dtype=float)
    return (X - X.mean(axis=0)) @ np.asarray(components, dtype=float).T


def components_needed(eigenvalues, share):
    ratios = np.sort(np.asarray(eigenvalues, dtype=float))[::-1] / np.sum(eigenvalues)
    return int(np.searchsorted(np.cumsum(ratios), share - 1e-12) + 1)
